#include <sstream>
struct Interval { int lo, hi; };
std::ostream& operator<<(std::ostream& out, const Interval& x) {
    // TODO: scrivi [lo,hi] sullo stream ricevuto e restituiscilo.
    out << '[' << x.lo << ',' << x.hi << ']';
    return out;
}
int main() {
    int a=0,b=0,c=0,d=0;
    std::cin >> a >> b >> c >> d;
    std::ostringstream text;
    text << Interval{a,b} << " | " << Interval{c,d};
    std::cout << text.str() << '\n';
}

