#include <iostream>
#include <vector>
class Samples {
    std::vector<int> values_;
public:
    Samples(int a, int b) : values_{a,b} {}
    int& at(int i) { return values_.at(i); }
    int at(int i) const { return values_.at(i); }
};
int main() {
    int a=0,b=0,delta=0;
    std::cin >> a >> b >> delta;
    Samples original(a,b);
    // TODO: costruisci una copia, poi una destinazione assegnata.
    Samples copy = original;
    Samples assigned(0,0);
    assigned = original;
    copy.at(0) += delta;
    assigned.at(1) -= delta;
    // TODO: applica delta alla prima cella di copy;
    // sottrai delta alla seconda cella di assigned.
    const Samples& view = original;
    std::cout << view.at(0) << ' ' << view.at(1) << ' '
              << copy.at(0) << ' ' << copy.at(1) << ' '
              << assigned.at(0) << ' ' << assigned.at(1) << '\n';
}

